// ═══ CUSTOM COLLECTOR: comma-separated uppercase string ═══
Collector<String, StringBuilder, String> upperCsvCollector = Collector.of(
    StringBuilder::new,                              // supplier: create container
    (sb, s) -> {                                     // accumulator: add one element
        if (!sb.isEmpty()) sb.append(", ");
        sb.append(s.toUpperCase());
    },
    (sb1, sb2) -> {                                  // combiner: merge for parallel
        if (!sb1.isEmpty() && !sb2.isEmpty()) sb1.append(", ");
        return sb1.append(sb2);
    },
    StringBuilder::toString                          // finisher: SB → String
);

String result = Stream.of("reliance", "tcs", "hdfc")
    .collect(upperCsvCollector);
// "RELIANCE, TCS, HDFC"

// ═══ CUSTOM COLLECTOR: collect to unmodifiable sorted set ═══
Collector<String, TreeSet<String>, Set<String>> sortedSetCollector = Collector.of(
    TreeSet::new,                                     // supplier
    TreeSet::add,                                     // accumulator
        (s1, s2) -> { s1.addAll(s2);
        return s1; },       // combiner
    Collections::unmodifiableSet                      // finisher: wrap as unmodifiable
);

Set<String> sorted = Stream.of("TCS", "RELIANCE", "HDFC", "TCS")
    .collect(sortedSetCollector);
// [HDFC, RELIANCE, TCS] — sorted, unique, unmodifiable

// ═══ IDENTITY_FINISH: skip finisher when container IS the result ═══
Collector<String, List<String>, List<String>> listCollector = Collector.of(
    ArrayList::new,                                   // supplier
    List::add,                                        // accumulator
        (l1, l2) -> { l1.addAll(l2);
        return l1; },       // combiner
    Collector.Characteristics.IDENTITY_FINISH          // finisher = identity (skip)
);
