package com.bank.collector;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class CustomCollectorTest {

    @Test void upperCsvCollector() {
        Collector<String, StringBuilder, String> collector = Collector.of(
            StringBuilder::new,
            (sb, s) -> { if (!sb.isEmpty()) sb.append(", "); sb.append(s.toUpperCase()); },
                (sb1, sb2) -> { if (!sb1.isEmpty() && !sb2.isEmpty()) sb1.append(", ");
                return sb1.append(sb2); },
            StringBuilder::toString);

        String result = Stream.of("reliance", "tcs", "hdfc").collect(collector);
        assertThat(result).isEqualTo("RELIANCE, TCS, HDFC");
    }

    @Test void unmodifiableSortedSetCollector() {
        Collector<String, TreeSet<String>, Set<String>> collector = Collector.of(
            TreeSet::new, TreeSet::add,
            (s1, s2) -> { s1.addAll(s2); return s1; },
            Collections::unmodifiableSet);

        Set<String> result = Stream.of("TCS", "RELIANCE", "HDFC", "TCS").collect(collector);
        assertThat(result).containsExactly("HDFC", "RELIANCE", "TCS");
        assertThatThrownBy(() -> result.add("X")).isInstanceOf(UnsupportedOperationException.class);
    }

    @Test void parallelUsesCombiber() {
        Collector<Integer, List<Integer>, List<Integer>> collector = Collector.of(
            ArrayList::new, List::add,
            (l1, l2) -> { l1.addAll(l2); return l1; },
            Collector.Characteristics.IDENTITY_FINISH);

        List<Integer> result = IntStream.rangeClosed(1, 1000).boxed()
            .parallel().collect(collector);
        assertThat(result).hasSize(1000);
    }
}
