package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.stream.Collector;
import static org.assertj.core.api.Assertions.assertThat;

class CustomCollectorTest {

    @Test
    void customCollectorBuildsStatement() {
        List<String> txns = List.of("DEP:5000", "WDR:2000");

        String statement = txns.stream().collect(Collector.of(
            StringBuilder::new,                              // supplier
            (sb, t) -> sb.append(t).append(";"),             // accumulator
            StringBuilder::append,                           // combiner
            StringBuilder::toString));                       // finisher

        assertThat(statement).isEqualTo("DEP:5000;WDR:2000;");
    }
}
